    public static IReadOnlyCollection<string> Keys => Text.Keys.Select(key => "extension." + key).ToArray();
    internal static bool TryTranslate(string locale, string key, out string value)
    {
        if (key.StartsWith("extension.", StringComparison.Ordinal) && Text.TryGetValue(key[10..], out var values))
        { value = values[locale switch { "en" => 1, "fr" => 2, "it" => 3, _ => 0 }]; return true; }
        value = ""; return false;
    }
